import json

def transform(grid):
    rows = len(grid)
    cols = len(grid[0])
    background = 5

    result = [row[:] for row in grid]

    # Find all complete rectangles
    rectangles = []
    visited = set()

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != background and (r, c) not in visited:
                visited.add((r, c))
                border_color = grid[r][c]

                # Find right boundary (scan right from this point, staying in bounds)
                c_right = c
                try:
                    while c_right < cols - 1 and grid[r][c_right + 1] == border_color:
                        c_right += 1
                except:
                    pass

                # Find down boundary (scan down from this point, staying in bounds)
                r_bottom = r
                try:
                    while r_bottom < rows - 1 and grid[r_bottom + 1][c] == border_color:
                        r_bottom += 1
                except:
                    pass

                # Verify complete rectangle with this border color (no out of bounds)
                if c_right < cols - 1 or r_bottom < rows - 1:
                    c_right = c  # invalid, reset
                    r_bottom = r

                # Check if it's a valid rectangle (same color on all four sides)
                if r_bottom == r and c_right == c:
                    continue

                # Top edge check
                top_ok = True
                for k in range(c, c_right + 1):
                    if grid[r][k] != border_color:
                        top_ok = False
                        break

                if not top_ok:
                    continue

                # Bottom edge check
                bottom_ok = True
                for k in range(c, c_right + 1):
                    if grid[r_bottom][k] != border_color:
                        bottom_ok = False
                        break

                if not bottom_ok:
                    continue

                # Left edge check
                left_ok = True
                for k in range(r, r_bottom + 1):
                    if grid[k][c] != border_color:
                        left_ok = False
                        break

                if not left_ok:
                    continue

                # Right edge check
                right_ok = True
                for k in range(r, r_bottom + 1):
                    if grid[k][c_right] != border_color:
                        right_ok = False
                        break

                if not right_ok:
                    continue

                # It's a valid rectangle! Fill interior.
                width = c_right - c + 1
                height = r_bottom - r + 1
                frame_size = width  # use width as frame size

                # Determine fill color
                if border_color % 2 == 0:  # even border
                    fill = border_color + 1
                else:  # odd border
                    fill = 5 - border_color

                print(f"Found rectangle at ({r},{c}) to ({r_bottom},{c_right}), color={border_color}, fill={fill}")

                # Fill interior (not including border cells)
                for ir in range(r+1, r_bottom):
                    for ic in range(c+1, c_right):
                        if grid[ir][ic] == background:
                            result[ir][ic] = fill

                # Mark all cells in rectangle as visited
                for k in range(r, r_bottom+1):
                    for k2 in range(c, c_right+1):
                        visited.add((k, k2))

    return result

